	SoftwareUpdateEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSoftwareUpdateEvent
     */
    @EventHandler
    public void handle( CreateSoftwareUpdateEvent event) {
        entityManager.persist(new SoftwareUpdate(event.getSoftwareUpdateId(), event.getVersion(), event.getAppliedDate(), event.getDevice(), event.getUpdateType()));
    }

    /*
     * @param	event UpdateSoftwareUpdateEvent
     */
    @EventHandler
    public SoftwareUpdate handle( UpdateSoftwareUpdateEvent event) {
    	entityManager.merge(new SoftwareUpdate(event.getSoftwareUpdateId(), event.getVersion(), event.getAppliedDate(), event.getDevice(), event.getUpdateType()));
    }
    
    /*
     * @param	event DeleteSoftwareUpdateEvent
     */
    @EventHandler
    public void on( DeleteSoftwareUpdateEvent event) {
    	SoftwareUpdate entity = new SoftwareUpdate();
   
    	// ------------------------------------------
    	// apply the SoftwareUpdateId
    	// ------------------------------------------
    	entity.setSoftwareUpdateId( event.getSoftwareUpdateId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
